import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"31、【鹹】 艮下兌上","description":"周易尚氏學 - 31、【鹹】 艮下兌上","frontmatter":{"title":"31、【鹹】 艮下兌上","description":"周易尚氏學 - 31、【鹹】 艮下兌上"},"headers":[],"relativePath":"classics/shangshi/036.md","filePath":"classics/shangshi/036.md"}'),s={name:"classics/shangshi/036.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_31、【鹹】-艮下兌上" tabindex="-1">31、【鹹】 艮下兌上 <a class="header-anchor" href="#_31、【鹹】-艮下兌上" aria-label="Permalink to “31、【鹹】 艮下兌上”">​</a></h1><p>鹹感也。歸藏曰欽。詩秦風憂心欽欽。傳思望之。心中欽欽然。蓋以少男仰求少女。有欽慕之情。是欽亦有感意。與鹹義同。六爻皆有應。故曰亨利貞。少女在前。肖男在後。而艮為求。兌為悅。艮男求女。兌悅應之。得婚姻之正。故曰取女吉。</p><p>彖曰。鹹。感也。柔上而剛下。二氣感應以相與。止而悅。男下女。是以亨利貞。取女吉也。天地感而萬物化生。聖人感人心而夫下和平。觀其所感。而天地萬物之情可見矣。</p><p>否三上交。故曰柔上而剛下。山澤通氣。故曰二氣感應以相與。艮止兌悅。故曰止而悅。兌上艮下。故曰男下女。天地感即陰陽和合。和合則萬物生。聖人感人則仁義兼施。仁義俠（左水）則天下和平。蓋天地萬物之事。莫不由感而通。由感而成。而其所以能感之故則情也。故曰其情可見。</p><p>象曰。山上有澤。鹹。君子以虛受人。</p><p>艮為君子。艮男下兌女。卑以自牧。故曰以虛受人。虞翻曰。否坤為虛。乾為人。今坤虛。三受上。故以虛受人。</p><p>初六。鹹其拇。</p><p>拇。釋文馬鄭薛雲。足大指也。初在下震交。故曰成其拇。鹹及拇。則欲行矣。</p><h3 id="象曰。鹹其拇。志在外也。" tabindex="-1">象曰。鹹其拇。志在外也。 <a class="header-anchor" href="#象曰。鹹其拇。志在外也。" aria-label="Permalink to “象曰。鹹其拇。志在外也。”">​</a></h3><p>外謂四。初應在四。初四相上下。則各當其位。足者人所恃以行。今感在拇。故欲之外也。巽伏故亦為志。見易林。亦失傳象也。</p><p>六二。成其腓。兇。居吉。</p><p>脛腓所恃以行。感及於腓。則欲前進。乃進而兇者何也。按二當位。承陽有應。與革二至上同。革六二徵吉。此應與之同。然而兇者。以革義取革新。故利於徵。若鹹則義取陰陽相感。感在五為正應。乃三四亦陽。二獨與五。則為三四所忌。故動兇居吉。此與同人六二同。二同於五。原為正應。然而吝者。以三四亦陽。二不與同而獨同五。則招忌也。其故皆在三四。近比三則失五之正應。遠應五則有近不承陽之嫌。遁六二蟄以牛革。亦戒其動。以遁二與同人鹹體同也。腓。說文脛端（左月）也。喘（左月）。說文腓腸也。段玉裁雲。腓腸謂脛骨後之肉。腫之言肥。似中有腸者。故曰腓腸。按段釋腓腸。至為明晰。即今俗所謂腿肚也。莊子天下篇。禹腓無跋（左月）。注跋（左月）細毛也。腓因勞受摩揩。故跋（左月）不生。然則腓為脛肚明矣。人之行恃脛。感及於脛。必前進矣、進則有咎。故曰兇。居則不動而承陽。故曰居吉。此爻兇義。鮮有詳其故者。崔憬謂二應五。失艮止義。惠棟謂二比三。失五正應。義皆未備。</p><h3 id="象曰。雖兇居吉。順不害也。" tabindex="-1">象曰。雖兇居吉。順不害也。 <a class="header-anchor" href="#象曰。雖兇居吉。順不害也。" aria-label="Permalink to “象曰。雖兇居吉。順不害也。”">​</a></h3><p>二承陽有應。當位。本無兇理。象辭恐人生疑。故釋其故。言爻辭雖雲動兇居吉。然陰順陽為天職。六二但上承諸陽。亦無害也。傳意似重近取。不必遠應也。翼經之大。莫過於是。</p><p>九三。鹹其股。執其隨。往吝。</p><p>巽為股。股在腓上。故鹹及於股。陽遇陽則窒。上雖有應。不能往也。往則為四五所忌而吝生矣。若初二則隨三者也。三下履重陰。止於是可矣。執者止也。止於三下比於陰。不必前進。否則吝窮也。</p><h3 id="象曰。鹹其股。亦不處也。志在隨人。所執下也。" tabindex="-1">象曰。鹹其股。亦不處也。志在隨人。所執下也。 <a class="header-anchor" href="#象曰。鹹其股。亦不處也。志在隨人。所執下也。" aria-label="Permalink to “象曰。鹹其股。亦不處也。志在隨人。所執下也。”">​</a></h3><p>股所以行。故曰不處。巽為志。乾為人。言初二志在隨三。故三之所執。宜於下也。</p><p>九四。貞吉。悔亡。憧憧往來。朋從爾思。</p><p>四不當位。承乘皆陽。故必貞定無為。方免悔吝。朋謂初。爾謂四。憧撞思不定也。蓋四來應初則三害之。初往應四。則二害之。故初四不宜動。宜靜。然阻愈多則感愈切。朋從爾思者。言初不得應陽。而慕思四也。</p><h3 id="象曰。貞吉悔亡。未感害也。憧憧往來。未光大也。" tabindex="-1">象曰。貞吉悔亡。未感害也。憧憧往來。未光大也。 <a class="header-anchor" href="#象曰。貞吉悔亡。未感害也。憧憧往來。未光大也。" aria-label="Permalink to “象曰。貞吉悔亡。未感害也。憧憧往來。未光大也。”">​</a></h3><p>下系雲。凡易之情。近而不相得則兇。或害之。三近四。二近初。然三亦陽。為四敵。二亦陰。為初敵。故二三為初四害。知其害而不動。害斯免矣。故曰未感害也。初四相上下成離。離為光大。今不能相上下。故曰未光大。</p><p>九五。鹹其每（左月）。無悔。</p><p>每（左月）。說文背脊肉也。鄭虞同。伏艮。艮為背。故曰鹹每（左月）當位得中。故無悔。感居人身之上。故象曰志末。末謂上六。言九五感上。近而無阻。故無悔也。案五正應在二。而舍二感上者。以三四害之也。</p><h3 id="象曰。鹹其每-左月-。志末也。" tabindex="-1">象曰。鹹其每（左月）。志末也。 <a class="header-anchor" href="#象曰。鹹其每-左月-。志末也。" aria-label="Permalink to “象曰。鹹其每（左月）。志末也。”">​</a></h3><p>大過雲。本末弱。以上為末也。茲曰志末。謂五為三四所阻。不能應二。故舍遠取近。感在上也。</p><p>上六。鹹其輔頰舌。</p><p>虞翻曰。耳目之間日輔頰。按說文。輔。人頰車也。頰。面旁也。左傳輔車相依注。輔輸頰。車牙車。正義雲。易以輔頰舌三進並言。則三物也。故鄭注頤卦雲。頤者口車輔也。震動於下。又止於上。口車動而上。因輸嚼物以養人。按鄭所謂口車即牙車。牙車在口下。故曰動而上。輔在口上。故曰因輔嚼物以養人。是輔與牙車對。在口中，頰在面旁。居口上。與頤連。不過頰在上。頤在下。頰以骨言。頤以肉言耳。是輸與頰確為二物。又皆為口之屬。故與舌並言。兌為口為言。輔頰舌皆兌象。所用以言者。感及於是。則言說多矣。故象日滕口說。來矣鮮雲。舌動則輔應而頰隨之。三者相須用事。皆所以言者。皆兌象。</p><h3 id="象曰。鹹其輔頰舌。滕口說也。" tabindex="-1">象曰。鹹其輔頰舌。滕口說也。 <a class="header-anchor" href="#象曰。鹹其輔頰舌。滕口說也。" aria-label="Permalink to “象曰。鹹其輔頰舌。滕口說也。”">​</a></h3><p>釋文。滕達也。九家作乘。虞作滕。鄭雲送也。按鄭虞說非也。朱子雲。滕與騰通。即達也。李鼎祚本正作騰。</p>',30)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
